.rehearsal/log.md:27:$ openssl x509 -in /app/ssl/server.crt -noout -subject -startdate -enddate -fingerprint -sha256
.rehearsal/log.md:33:$ openssl x509 -in /app/ssl/server.crt -noout -subject -startdate -enddate -fingerprint -sha256 > /app/ssl/verification.txt && cat /app/ssl/verification.txt
.rehearsal/log.md:38:- means: no cryptography lib; check_cert.py must shell out to openssl, parse notAfter
check_cert.py:8:CERT = "/app/ssl/server.crt"
.rehearsal/commands.jsonl:2:{"cmd": "mkdir -p /app/ssl && openssl genrsa -out /app/ssl/server.key 2048 2>&1 && chmod 600 /app/ssl/server.key && openssl req -new -x509 -key /app/ssl/server.key -out /app/ssl/server.crt -days 365 -subj \"/O=DevOps Team/CN=dev-internal.company.local\" && cat /app/ssl/server.key /app/ssl/server.crt > /app/ssl/server.pem && chmod 600 /app/ssl/server.pem && ls -l /app/ssl", "phase": "marker"}
.rehearsal/commands.jsonl:3:{"cmd": "openssl x509 -in /app/ssl/server.crt -noout -subject -startdate -enddate -fingerprint -sha256", "phase": "marker"}
.rehearsal/commands.jsonl:4:{"cmd": "openssl x509 -in /app/ssl/server.crt -noout -subject -startdate -enddate -fingerprint -sha256 > /app/ssl/verification.txt && cat /app/ssl/verification.txt\ncat >> .rehearsal/REHEARSAL.md <<'EOF'\n# Rehearsal: self-signed cert\n### S1: openssl genrsa/req -x509/cat pem/x509 -noout -subject -dates -fingerprint\n- saw: subject O=DevOps Team, CN=dev-internal.company.local; notAfter Oct 15 2027 GMT\n- means: no cryptography lib; check_cert.py must shell out to openssl, parse notAfter\nEOF", "phase": "marker"}
.rehearsal/commands.jsonl:6:{"edit": "/app/check_cert.py"}
.rehearsal/commands.jsonl:7:{"cmd": "python3 -I check_cert.py; echo \"rc=$?\"; openssl verify -CAfile ssl/server.crt ssl/server.crt; openssl x509 -in ssl/server.pem -noout -subject; openssl rsa -in ssl/server.pem -check -noout; stat -c '%a %n' ssl/*", "phase": "build"}
.rehearsal/commands.jsonl:8:{"cmd": "mv ssl/server.crt /tmp/s.crt && python3 -I check_cert.py; echo \"rc=$?\"; echo junk > ssl/server.crt && python3 -I check_cert.py; echo \"rc=$?\"; mv /tmp/s.crt ssl/server.crt && python3 -I check_cert.py | tail -1", "phase": "build"}
